INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('evensong', 'Evensong', '', '', 'Kevin Ngo', '', 'X', NULL, '244', 0, 2026, 'action', '["动作","魂like"]', 250, 0.1, 'io', 'https://evensong-phi.vercel.app/', 0, 1, 1, 1, 1, 1, 1, 'mid', 'x', '画面就在原页里', '沉没的主教堂里，只打这一场。画面就在原页。', 'One fight in a sunken cathedral. The original page is the picture.', 'Kevin Ngo 用 Fable 5.2 做的魂like Boss 战，原页托管在 evensong-phi.vercel.app。试玩舱直接打开完整原作，不是站内示意。封面是作者公开的分享卡。', 'Kevin Ngo’s Fable 5.2 soulslike boss fight, hosted at evensong-phi.vercel.app. The cabin opens the full original. Cover is the author’s public share card.', 'assets/posters/evensong.jpg', 1200, 630, 'center', '["assets/posters/evensong.jpg"]', '[[1200,630]]', '[0,0,0,0,0]', 0, 1794591927039, 'The picture is on the original page', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('breach', '穿越火线', 'CrossFire', 'chuanyuehuoxian cf', 'hanyue.io', '', '', NULL, '19', 0, 2026, 'action', '["射击","联机","CF"]', 20, 0.1, 'io', 'https://cf.hanyue.io/', 0, 0, 1, 1, 1, 1, 1, 'mid', 'hosted', '起个名字就能进', '玩CF。起个名字进大厅，运输船等多图可打。', 'Play CF. Pick a name, walk into the lobby, fight on Transport Ship and other maps.', 'hanyue.io 托管的穿越火线网页联机局，原页是 BREACH 大厅。试玩舱直接打开 https://cf.hanyue.io/，不是站内示意。', 'A CrossFire web lobby hosted at cf.hanyue.io (BREACH). The cabin opens the original page.', 'assets/posters/breach.jpg', 960, 540, 'center', '["assets/posters/breach.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 1, 1794591927039, 'Pick a name and walk in', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('warm-toy-room', '双人成行 · 暖光玩具房', 'It Takes Two · Warm Toy Room', 'shuangrenchengxing nanguang wanju', '大肥鱼', '', '', NULL, '26', 0, 2026, 'action', '["平台","联机"]', 35, 0.1, 'io', 'https://v25.dafeiyugame.site/', 0, 0, 1, 1, 1, 1, 1, 'mid', 'hosted', '换人，把星星搬回家', '大肥鱼的双人成行网页试玩。在暖光玩具房里跑跳、换人，收集五枚星光。', 'Da Fei Yu’s It Takes Two web demo. Run, swap, and gather five starlights in a warm toy room.', '原页托管在 v25.dafeiyugame.site，V30 网页试玩。试玩舱打开完整原作，不是站内示意。封面是启动页实机。', 'Hosted at v25.dafeiyugame.site, V30 web demo. The cabin opens the full original. Cover is the live splash.', 'assets/posters/warm-toy-room.jpg', 960, 540, 'center', '["assets/posters/warm-toy-room.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 2, 1794591927039, 'Swap, bring the stars home', 'listed', 'dafeiyu');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('feiche-3d', 'QQ飞车', 'QQ Speed', 'qqfeiche feiche', '', '', '腾讯（IP）', NULL, '67', 0, 2026, 'action', '["竞速","工坊"]', 20, 0.1, 'io', 'https://lf3-static.bytednsdoc.com/obj/eden-cn/nulojnulwlo/qqfeiche3d/index.html', 0, 1, 1, 1, 1, 1, 1, 'mid', 'fable52', '氮气一开就能漂', '漂移攒能量，氮气和道具，四条复古赛道。原页可玩。', 'Drift for energy, nitro and items, four retro tracks. The original page is playable.', 'QQ飞车 3D 网页局，字节静态托管。试玩舱打开完整原页。', 'QQ Speed 3D in the browser, hosted on ByteDance CDN. The cabin opens the full original.', 'assets/posters/feiche-3d.jpg', 960, 540, 'center', '["assets/posters/feiche-3d.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 3, 1794591927039, 'Nitro on, drift away', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('hextech-aram', '英雄联盟 · 海克斯大乱斗', 'League of Legends · Hextech ARAM', 'yingxionglianmeng yxlm lol aram haikesidaluandou', 'hanyue.io', '', '', NULL, '41', 0, 2026, 'action', '["MOBA","联机"]', 220, 0.1, 'io', 'https://lol.hanyue.io/', 0, 0, 1, 1, 1, 1, 1, 'mid', 'hosted', '选个英雄上冰桥', '选一个英雄，在冰桥上乱斗。原页可玩。', 'Pick a champion and brawl on the ice bridge. The original page is playable.', '英雄联盟海克斯大乱斗网页局，原页托管在 lol.hanyue.io。试玩舱打开完整原作。', 'A Hextech ARAM web brawl hosted at lol.hanyue.io. The cabin opens the full original.', 'assets/posters/hextech-aram.jpg', 960, 540, 'center', '["assets/posters/hextech-aram.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 4, 1794591927039, 'Pick a champion, hit the ice', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('last-light', 'Last Light', '', '', 'Deny224', '', 'X', NULL, '本周上架', 0, 2026, 'action', '["生存","动作"]', 70, 0.12, 'story', '', 0, 0, 1, 1, 1, 1, 1, 'mid', 'x', '灯笼就是血条', '灯笼就是血条。浏览器里直接开的 3D 夜林。', 'The lantern is the health bar. A 3D night wood that opens in the browser.', '作者 Deny224 在 X 发出的免费浏览器生存。试玩舱用一段守火选择代替完整夜林，不是原作搬迁。', 'Deny224 posted this free browser survival on X. The cabin uses a short fire-watch in place of the full wood — not a port of the original.', 'assets/posters/last-light-1.jpg', 1568, 722, 'center 42%', '["assets/posters/last-light-1.jpg","assets/posters/last-light-3.jpg","assets/posters/last-light-2.jpg"]', '[[1568,722],[1568,722],[1568,722]]', '[0,0,0,0,0]', 5, 1794591927039, 'The lantern is the health bar', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('akoben', 'AKOBEN', '', '', 'Eddie Forson', '', 'X', NULL, '本周上架', 0, 2026, 'action', '["动作","Boss"]', 25, 0.12, 'io', '', 0, 0, 0, 1, 1, 1, 0, 'mid', 'x', '', '六足攻城机走进节日集市。打断两只膝盖，它就会跪下。', 'A six-legged siege walker enters a festival market. Break both knees and it kneels.', 'Kiseki Labs 的浏览器序章 Boss「The Sovereign」。封面是作者发在 X 上的角色海报。试玩舱用 IO 场感代替机甲战。', 'Kiseki Labs’ browser prologue boss, The Sovereign. Cover is the character poster the author posted on X. The cabin uses an IO arena in place of the mech fight.', 'assets/posters/akoben.jpg', 1080, 1350, 'center 35%', '["assets/posters/akoben.jpg"]', '[[1080,1350]]', '[0,0,0,0,0]', 6, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('we-fishing', 'We Fishing', '', '', 'Mangolotis', '', 'X', NULL, '本周上架', 0, 2026, 'idle', '["放置","钓鱼"]', 40, 0.1, 'clicker', '', 0, 0, 0, 1, 1, 1, 1, 'mid', 'x', '钓鱼、听歌、留言', '钓鱼、听歌、留一句。作者说玩法几乎什么也没有。', 'Fish, listen to a song, leave a line. The author says there is almost no gameplay.', 'Mangolotis 在 X 发出的网页钓鱼。封面是秋日池塘的实机。试玩舱只保留点击收杆的手感。', 'Mangolotis posted this web fishing game on X. Cover is a live shot of the autumn pond. The cabin keeps only the click-to-reel feel.', 'assets/posters/we-fishing.jpg', 1787, 806, 'center 58%', '["assets/posters/we-fishing.jpg"]', '[[1787,806]]', '[0,0,0,0,0]', 7, 1794591927039, 'Fish, listen, leave a note', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('mustache-protocol', 'Mustache Protocol', '', '', 'Henry Cavill', '', 'X', NULL, '本周上架', 0, 2026, 'action', '["动作","像素"]', 70, 0.12, 'io', '', 0, 0, 1, 1, 1, 1, 0, 'mid', 'x', '', '胡子骑士拿着电锯剑。浏览器里能开。', 'A mustache knight with a chainsaw sword. It opens in the browser.', 'ScreenTime 在 X 转的 Henry Cavill AI 网页游戏。封面是作者放出的像素立绘。试玩舱不模拟原作关卡。', 'A Henry Cavill AI web game ScreenTime posted on X. Cover is the author’s pixel standee. The cabin does not simulate the original stages.', 'assets/posters/mustache-1.jpg', 1400, 1400, 'center 22%', '["assets/posters/mustache-1.jpg","assets/posters/mustache-2.jpg"]', '[[1400,1400],[1400,1400]]', '[0,0,0,0,0]', 8, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('laps', 'Laps', '', '', 'Dan Clarke', '', 'X', NULL, '本周上架', 0, 2026, 'action', '["竞速","桌面"]', 50, 0.1, 'io', '', 0, 0, 0, 1, 1, 1, 1, 'short', 'x', '课桌上的迷你圈速', '数学课本旁边在赛车。Xbox 自带浏览器也能开。', 'A race next to a math book. The Xbox’s own browser can open it.', 'Dan Clarke 周末做的网页圈速，封面是餐桌上的实机。试玩舱用 IO 移动代替完整赛车。', 'A web time-trial Dan Clarke made over a weekend. Cover is a live shot on a dining table. The cabin uses IO movement in place of the full racer.', 'assets/posters/laps-2.jpg', 1920, 1080, 'center 48%', '["assets/posters/laps-2.jpg","assets/posters/laps-1.jpg"]', '[[1920,1080],[1920,1080]]', '[0,0,0,0,0]', 9, 1794591927039, 'Mini laps on a desk', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('lost-transmission', 'The Lost Transmission', '', '', 'James P', '', 'X', NULL, '本周上架', 0, 2026, 'story', '["叙事","终端"]', 155, 0.1, 'story', '', 0, 0, 0, 1, 1, 0, 0, 'mid', 'x', '', 'IRIS 在给你画一张宇宙航图。燃料只有 28。', 'IRIS is drawing you a star chart. Fuel is 28.', '像素科幻终端。封面是作者在 X 发出的星系地图实机。试玩舱用短选择带你进门。', 'A pixel sci-fi terminal. Cover is the galaxy map the author posted on X. The cabin uses a short choice to get you in the door.', 'assets/posters/lost-transmission.jpg', 1280, 720, 'center', '["assets/posters/lost-transmission.jpg"]', '[[1280,720]]', '[0,0,0,0,0]', 10, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('saltline', 'Saltline is Dark', '', '', '@imteccin', '', 'X', NULL, '3100', 0, 2026, 'action', '["工坊","射击"]', 70, 0.08, 'story', '', 0, 1, 1, 1, 1, 1, 1, 'mid', 'x', '码头上的清场结算', 'Berth 4 清场完毕。作者说 Fable 5.2 疯了。', 'Berth 4 is clear. The author says Fable 5.2 is insane.', 'X 用户 @imteccin 发出的 Fable 5.2 实机：码头、结算板、Redeploy。试玩舱用短选择表现清场之后，不是原作关卡。', '@imteccin posted this Fable 5.2 capture on X: dock, tally board, Redeploy. The cabin uses a short choice after the wipe — not an original stage.', 'assets/posters/fable-52.jpg', 2148, 1196, 'center 46%', '["assets/posters/fable-52.jpg"]', '[[2148,1196]]', '[0,0,0,0,0]', 11, 1794591927039, 'A dock, a wipe, a tally', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('fluff-bat', 'Fluff Bat Flight', '', '', 'BlackLight.ink', '', 'X', NULL, '本周上架', 0, 2026, 'action', '["动作","休闲"]', 300, 0.1, 'io', '', 0, 0, 0, 1, 1, 0, 0, 'short', 'x', '', '选一只绒蝠，穿过宫殿，捡蛋，躲大蒜。', 'Pick a fluff bat, fly the palace, grab eggs, dodge garlic.', '为 Fluff Bat 比赛做的网页飞行。封面是作者发在 X 上的海报。试玩舱用 IO 场感代替拍翅。', 'A web flyer for the Fluff Bat contest. Cover is the poster the author posted on X. The cabin uses IO feel in place of wingbeats.', 'assets/posters/fluff-bat.jpg', 1600, 900, 'center 40%', '["assets/posters/fluff-bat.jpg"]', '[[1600,900]]', '[0,0,0,0,0]', 12, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('sams-pizza', 'A Day at Sam''s Pizza', '', '', 'CollectorDev', '', 'X', NULL, '本周上架', 0, 2026, 'puzzle', '["模拟","像素"]', 50, 0.1, 'story', '', 0, 0, 0, 1, 0, 0, 0, 'short', 'x', '', '夜里的披萨店。客人要一块，你来配单。', 'A pizza shop at night. A guest wants a slice. You build the order.', 'CollectorDev 在 X 发出的网页店。封面是点单实机。试玩舱用短选择代替配餐。', 'CollectorDev posted this web shop on X. Cover is a live order screen. The cabin uses a short choice in place of making the pie.', 'assets/posters/sams-pizza-2.png', 800, 600, 'center 40%', '["assets/posters/sams-pizza-2.png","assets/posters/sams-pizza-1.png"]', '[[800,600],[800,600]]', '[0,0,0,0,0]', 13, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('water-keeps', 'What the Water Keeps', '', '', 'Kevin Ngo', '', '', NULL, '314', 0, 2026, 'story', '["探索","叙事"]', 200, 0.1, 'story', '', 0, 1, 1, 1, 1, 1, 1, 'mid', 'fable52', '八界泛舟', '坐船穿过八个不像同一世界的水域。灯笼亮着，你可以自己划。', 'Row through eight waters that do not feel like one world. Lanterns stay on. You paddle.', 'Kevin Ngo 用 Fable 5.2 做的浏览器泛舟。X 上这周还在转。封面来自 fable52.games。试玩舱用短选择代替八界。', 'Kevin Ngo’s browser boat, made in Fable 5.2. Still circulating on X this week. Cover from fable52.games. The cabin uses short choices in place of the eight worlds.', 'assets/posters/water-keeps.jpg', 960, 540, 'center', '["assets/posters/water-keeps.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 14, 1794591927039, 'Eight waters, one boat', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('mothlight', 'MOTHLIGHT // Vesper-9', '', '', '', 'Fable 5.2', 'fable52.games', NULL, '320', 0, 2026, 'action', '["竞速","赛博"]', 300, 0.1, 'io', '', 0, 1, 1, 1, 1, 1, 0, 'mid', 'fable52', '', '雨夜里穿过五座城区，把十二道光门串起来。', 'Cut through five districts in the rain and string twelve light gates together.', 'fable52.games 收录的单文件赛博竞速。封面是原站缩略图。试玩舱用 IO 移动代替完整赛道。', 'A single-file cyber racer listed on fable52.games. Cover is the original thumbnail. The cabin uses IO movement in place of the full track.', 'assets/posters/mothlight.jpg', 960, 540, 'center', '["assets/posters/mothlight.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 15, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('bayhaven', 'Bayhaven', '', '', '', 'Fable 5.2', 'fable52.games', NULL, '330', 0, 2026, 'action', '["开放世界","驾驶"]', 40, 0.1, 'io', '', 0, 1, 1, 1, 1, 1, 0, 'mid', 'fable52', '', '一场现场写出来的开放世界。开车，逛城，把旧账了结。', 'An open world written on the spot. Drive, walk the city, settle an old bill.', 'Fable 5.2 一次长会话写完的犯罪开放世界。封面来自 fable52.games。试玩舱不模拟整座城。', 'A crime open world written in one long Fable 5.2 session. Cover from fable52.games. The cabin does not simulate the whole city.', 'assets/posters/bayhaven.jpg', 960, 540, 'center', '["assets/posters/bayhaven.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 16, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('qingyun', '青云宗 · 御剑采灵', 'Qingyun Sect', 'qingyunzong yujiancailing qingyun', '', 'Fable 5.2', 'fable52.games', NULL, '199', 0, 2026, 'story', '["探索","飞行"]', 155, 0.1, 'io', '', 0, 1, 1, 1, 0, 1, 0, 'mid', 'fable52', '', '云海上面御剑。采二十缕灵气，把山门点亮。', 'Sword-fly over a sea of cloud. Gather twenty wisps and light the mountain gate.', 'Fable 5.2 仙侠飞行。封面来自 fable52.games。试玩舱不模拟完整御剑。', 'A xianxia flyer in Fable 5.2. Cover from fable52.games. The cabin does not simulate the full flight.', 'assets/posters/qingyun.jpg', 960, 540, 'center', '["assets/posters/qingyun.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 17, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('dustfall', 'Dustfall', '', '', '', 'Fable 5.2', 'fable52.games', NULL, '284', 0, 2026, 'action', '["开放世界","西部"]', 50, 0.1, 'story', '', 0, 1, 1, 1, 0, 1, 0, 'mid', 'fable52', '', 'Sorrel Basin 里骑马、打猎、打牌，把旧账结了。', 'Ride, hunt, and play cards in Sorrel Basin. Settle the old bill.', 'Fable 5.2 西部开放世界。封面来自 fable52.games。', 'A western open world in Fable 5.2. Cover from fable52.games.', 'assets/posters/dustfall.jpg', 960, 540, 'center', '["assets/posters/dustfall.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 18, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('blameless', 'BLAMELESS', '', '', '', 'Fable 5.2', 'fable52.games', NULL, '340', 0, 2026, 'action', '["射击","工坊"]', 145, 0.1, 'io', '', 0, 1, 1, 1, 0, 1, 0, 'mid', 'fable52', '', '凌晨 3:07，生产挂了。你亲自 kubectl exec 进去。', '03:07. Production is down. You kubectl exec in yourself.', '值班程序员题材的 FPS。封面来自 fable52.games。', 'An FPS about being on call. Cover from fable52.games.', 'assets/posters/blameless.jpg', 960, 540, 'center', '["assets/posters/blameless.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 19, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('pelican-bike', '鹈鹕骑自行车', 'Pelican Bike', 'tihu qizixingche', '', 'Fable 5.2', '字节 CDN', NULL, '346', 0, 2026, 'action', '["休闲","工坊"]', 200, 0.1, 'io', 'https://lf3-static.bytednsdoc.com/obj/eden-cn/nulojnulwlo/pelican-bike/index.html', 0, 1, 1, 1, 0, 1, 0, 'short', 'fable52', '', '戴头盔的鹈鹕沿着海岸骑车追鱼。原页可玩。', 'A helmeted pelican rides the coast and chases fish. The original page is playable.', '单文件休闲骑行。试玩舱打开字节托管的完整原页。', 'A single-file casual ride. The cabin opens the hosted original on ByteDance CDN.', 'assets/posters/pelican-bike.jpg', 960, 540, 'center', '["assets/posters/pelican-bike.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 20, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('pocket-soccer', 'Pocket Soccer 3D', '', '', '', 'Fable 5.2', 'fable52.games', NULL, '749', 0, 2026, 'action', '["体育","模拟"]', 130, 0.1, 'io', '', 0, 1, 1, 1, 0, 1, 0, 'mid', 'fable52', '', '七人制，有裁判、越位、红牌和点球。一整个 HTML。', 'Seven-a-side with a referee, offside, red cards, and pens. One HTML file.', 'fable52.games 上在玩最多的体育网页包之一。', 'One of the most-played sports packs on fable52.games.', 'assets/posters/pocket-soccer.jpg', 960, 540, 'center', '["assets/posters/pocket-soccer.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 21, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('emberdeep', 'Emberdeep', '', '', '', 'Fable 5.2', 'fable52.games', NULL, '55', 0, 2026, 'story', '["冒险","Roguelike"]', 25, 0.1, 'story', '', 0, 1, 0, 1, 0, 0, 0, 'mid', 'fable52', '', '火把在烧短。地牢只在这一份 HTML 里。', 'The torch is burning short. The dungeon lives in this one HTML file.', '单文件地牢下行。X 上有人转过火把视角。封面来自 fable52.games。', 'A single-file dungeon crawl. Someone posted the torch view on X. Cover from fable52.games.', 'assets/posters/emberdeep.jpg', 960, 540, 'center', '["assets/posters/emberdeep.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 22, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('jimao-cs', '几猫CS', 'Jimao CS', 'jimao jimaocs', '', 'Fable 5.2', 'fable52.games', NULL, '140', 0, 2026, 'action', '["射击","中文"]', 70, 0.1, 'io', '', 0, 1, 0, 1, 0, 0, 0, 'mid', 'fable52', '', '雨港换了几猫货柜的牌子。Saltline 的中文本地化。', 'The rain port now wears Jimao crates. A Chinese localization of Saltline.', 'Saltline 的中文重制。封面来自 fable52.games。', 'A Chinese remake of Saltline. Cover from fable52.games.', 'assets/posters/jimao-cs.jpg', 960, 540, 'center', '["assets/posters/jimao-cs.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 23, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('tidebell', 'Tidebell 潮钟', 'Tidebell', '', '', 'Fable 5.2', 'fable52.games', NULL, '193', 0, 2026, 'story', '["探索","水下"]', 210, 0.1, 'story', '', 0, 1, 0, 1, 0, 0, 0, 'mid', 'fable52', '', '从浅礁潜到深渊，叫醒七口睡着的潮钟。', 'Dive from the shallows to the abyss and wake seven sleeping tide bells.', 'Fable 5.2 水下探索。封面来自 fable52.games。', 'Underwater exploration in Fable 5.2. Cover from fable52.games.', 'assets/posters/tidebell.jpg', 960, 540, 'center', '["assets/posters/tidebell.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 24, 1794591927039, '', '', '');
