INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('tuktuk', 'TukTuk: وسّع يا باشا', '', '', '', 'Fable 5.2', 'fable52.games', NULL, '139', 0, 2026, 'action', '["驾驶","街机"]', 45, 0.1, 'io', '', 0, 1, 0, 1, 0, 0, 0, 'short', 'fable52', '', '开着嘟嘟车穿过开罗街道，躲开小巴和西瓜车。', 'Drive a tuk-tuk through Cairo. Dodge minibuses and watermelon carts.', '埃及街道驾驶。封面来自 fable52.games。', 'Street driving in Egypt. Cover from fable52.games.', 'assets/posters/tuktuk.jpg', 960, 540, 'center', '["assets/posters/tuktuk.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 29, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('hanford-reach', 'Hanford Reach', '', '', '', 'Fable 5.2', 'fable52.games', NULL, '85', 0, 2026, 'idle', '["模拟","建造"]', 90, 0.1, 'story', '', 0, 1, 0, 1, 0, 0, 0, 'mid', 'fable52', '', '哥伦比亚河边一座废镇。第一或第三人称把聚落建起来。', 'A dead town on the Columbia. First or third person, build the settlement.', '废镇建造。封面来自 fable52.games。', 'A ruin-town builder. Cover from fable52.games.', 'assets/posters/hanford-reach.jpg', 960, 540, 'center', '["assets/posters/hanford-reach.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 30, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('shuttle-strike', 'Shuttle Strike', '', '', '', 'Fable 5.2', 'fable52.games', NULL, '60', 0, 2026, 'action', '["体育","摄像头"]', 160, 0.1, 'io', '', 0, 1, 0, 1, 0, 0, 0, 'short', 'fable52', '', '摄像头盯着手。握拍、挥拍、扣杀。', 'The camera watches your hand. Grip, swing, smash.', '第一人称羽毛球，70 KB 单文件。封面来自 fable52.games。', 'First-person badminton, 70 KB, one file. Cover from fable52.games.', 'assets/posters/shuttle-strike.jpg', 960, 540, 'center', '["assets/posters/shuttle-strike.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 31, 1794591927039, '', '', '');
