INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('boring-game', 'Boring Game', '', '', '', 'Fable 5.2', 'fable52.games', NULL, '53', 0, 2026, 'idle', '["模拟","策略"]', 240, 0.1, 'story', '', 0, 1, 0, 1, 0, 0, 0, 'mid', 'fable52', '', '用真实地图在湾区挖地铁。选盾构，再过红头文件。', 'Dig a Bay Area metro on a real map. Pick a TBM, then clear the red tape.', '体素旧金山湾区。封面来自 fable52.games。', 'Voxel San Francisco Bay. Cover from fable52.games.', 'assets/posters/boring-game.jpg', 960, 540, 'center', '["assets/posters/boring-game.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 34, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('transport-ship', '穿越火线之运输船', 'CF · Transport Ship', 'chuanyuehuoxian yunshuchuan cf', '', '', '腾讯（IP）', NULL, '27', 0, 2026, 'action', '["射击","同人"]', 210, 0.1, 'io', 'https://lf3-static.bytednsdoc.com/obj/eden-cn/nulojnulwlo/cf-transport-ship/transport-ship.html', 0, 1, 1, 1, 0, 1, 0, 'mid', 'fable52', '', '经典运输船地图的浏览器重制。打人机。原页可玩。', 'A browser remake of the classic transport-ship map. Fight bots. The original page is playable.', '穿越火线运输船网页局，字节静态托管。试玩舱打开完整原页。', 'CrossFire transport-ship in the browser, hosted on ByteDance CDN. The cabin opens the full original.', 'assets/posters/transport-ship.jpg', 960, 540, 'center', '["assets/posters/transport-ship.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 35, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('saltline-online', '盐线行动 Online', 'Saltline Online', 'yanxian', '', 'Fable 5.2', 'fable52.games', NULL, '22', 0, 2026, 'action', '["射击","联机"]', 70, 0.1, 'io', '', 0, 1, 0, 1, 0, 0, 0, 'mid', 'fable52', '', 'Saltline 开了联机。五秒复活，港口混战。', 'Saltline went multiplayer. Five-second respawn, a port brawl.', 'Saltline 多人版。封面来自 fable52.games。', 'The multiplayer cut of Saltline. Cover from fable52.games.', 'assets/posters/saltline-online.jpg', 960, 540, 'center', '["assets/posters/saltline-online.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 36, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('misremember', 'MISREMEMBER', '', '', '', 'Fable 5.2', 'fable52.games', NULL, '53', 0, 2026, 'story', '["恐怖","探索"]', 280, 0.1, 'story', '', 0, 1, 0, 1, 0, 0, 0, 'mid', 'fable52', '', '有东西按你的记忆把童年的家重建了。你看着的时候，什么都不会变。', 'Something rebuilt your childhood house from your memory. While you watch, nothing changes.', '恐怖探索。封面来自 fable52.games。', 'Horror exploration. Cover from fable52.games.', 'assets/posters/misremember.jpg', 960, 540, 'center', '["assets/posters/misremember.jpg"]', '[[960,540]]', '[0,0,0,0,0]', 37, 1794591927039, '', '', '');
