INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('open-skies', 'Open Skies', '', '', '', 'Fable 5.2', 'fable52.games', NULL, '3', 0, 2026, 'idle', '["模拟","飞行"]', 210, 0.1, 'story', '', 0, 1, 0, 1, 0, 0, 0, 'mid', 'fable52', '', '地球上随便飞。真实机场、地形和天气，飞行学校一课一课教。', 'Fly anywhere on Earth. Real airports, terrain, weather. Flight school, lesson by lesson.', '地球飞行模拟。封面来自 fable52.games。', 'An Earth flight sim. Cover from fable52.games.', 'assets/posters/open-skies.jpg', 1280, 720, 'center', '["assets/posters/open-skies.jpg"]', '[[1280,720]]', '[0,0,0,0,0]', 41, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('beach-hamster', 'Beach Hamster', '', '', 'Tony M', '', 'X', NULL, '本周上架', 0, 2026, 'action', '["休闲","收集"]', 50, 0.1, 'io', '', 0, 0, 0, 1, 0, 0, 0, 'short', 'x', '', '海边捡沙钱。躲开浪、螃蟹和俯冲的海鸥。', 'Pick up sand dollars on the beach. Dodge waves, crabs, and diving gulls.', 'Tony M 昨天在 X 发出的浏览器新作，Stab the Finger Arcade。封面是作者原帖。', 'Tony M posted this browser game on X yesterday, Stab the Finger Arcade. Cover is the original post.', 'assets/posters/beach-hamster.jpg', 888, 926, 'center 40%', '["assets/posters/beach-hamster.jpg"]', '[[888,926]]', '[0,0,0,0,0]', 42, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('forkline', 'Forkline', '', '', 'Jason Von Holmes', '', 'X', NULL, '本周上架', 0, 2026, 'idle', '["模拟","贸易"]', 240, 0.1, 'clicker', '', 0, 0, 0, 1, 0, 0, 0, 'mid', 'x', '', '一艘贸易船，一笔要还的债。价格会动，星间行情会过期。', 'One trade ship, one debt to pay. Prices move. Star-lane quotes expire.', 'Jason Von Holmes 昨天在 X 发出的免费浏览器贸易。封面是作者原帖。', 'Jason Von Holmes posted this free browser trader on X yesterday. Cover is the original post.', 'assets/posters/forkline.jpg', 1200, 675, 'center', '["assets/posters/forkline.jpg"]', '[[1200,675]]', '[0,0,0,0,0]', 43, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('fable-multiplayer', 'Fable 5.2 联机局', 'Fable 5.2 Multiplayer', '', 'Ahmad K. Mozaffar', '', 'X', NULL, '本周上架', 0, 2026, 'action', '["工坊","联机"]', 145, 0.1, 'io', '', 0, 1, 0, 1, 0, 0, 0, 'mid', 'x', '', '几分钟做出能联机的一局，连资源都是现场生成的。', 'A multiplayer round in a few minutes. Even the assets are generated on the spot.', 'Ahmad 昨天在 X 发出的 Fable 5.2 联机演示。封面是作者原帖实机。', 'Ahmad posted this Fable 5.2 multiplayer demo on X yesterday. Cover is the author’s live capture.', 'assets/posters/fable-multiplayer.jpg', 1199, 445, 'center 30%', '["assets/posters/fable-multiplayer.jpg"]', '[[1199,445]]', '[0,0,0,0,0]', 44, 1794591927039, '', '', '');
