INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('cookie-clicker', 'Cookie Clicker', '', '', 'Orteil', '', '', 9.4, '128.6万', 0, 2013, 'idle', '["放置","点击"]', 70, 0.12, 'clicker', 'https://orteil.dashnet.org/cookieclicker/', 0, 0, 1, 0, 0, 1, 1, 'long', '', '没有关卡，也没有结局', '没有关卡，也没有结局。饼干会一直等你。', 'No levels. No ending. The cookies will wait.', '从一块饼干开始，点出烤箱、工厂和宇宙。本页试玩舱只保留点击与升级，完整宇宙在原作里。', 'Start with one cookie. Click out ovens, factories, a universe. This cabin keeps only click and upgrade. The full cosmos is in the original.', 'assets/posters/cookie-clicker.jpg', 1920, 1080, 'center 40%', '["assets/posters/cookie-clicker.jpg","assets/posters/cookie-2.jpg"]', '[[1920,1080],[1920,1080]]', '[2,3,8,27,60]', 59, 1794591927039, 'No levels. No ending.', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('2048', '2048', '', '', 'Gabriele Cirulli', '', '', 9.1, '96.2万', 0, 2014, 'puzzle', '["解谜","滑动"]', 50, 0.14, 'merge', 'https://play2048.co/', 0, 0, 1, 0, 0, 1, 0, 'short', '', '', '规则三秒就懂，512 开始手会抖。', 'The rule takes three seconds. Your hands start to shake at 512.', '在 4×4 格子里把数字合成 2048。试玩舱是完整规则的迷你局，刷新即可重开。', 'Slide tiles on a 4×4 grid until you make 2048. The cabin is a mini game with the full rule. Refresh to start over.', 'assets/posters/2048.jpg', 1200, 630, 'center', '["assets/posters/2048.jpg","assets/posters/2048.png"]', '[[1200,630],[548,549]]', '[3,5,12,31,49]', 60, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('a-dark-room', 'A Dark Room', '', '', 'Doublespeak Games', '', '', 9.6, '41.8万', 0, 2013, 'story', '["叙事","文字"]', 40, 0.04, 'story', 'https://adarkroom.doublespeakgames.com/', 0, 0, 0, 0, 0, 1, 0, 'long', '', '', '先把火点燃。其余的事，火光里会慢慢出现。', 'Light the fire first. The rest shows up in the glow.', '火堆、木头、门外的声音。试玩舱用一段原创短篇带你进门，不是原作剧情搬迁。', 'Fire, wood, a sound outside the door. The cabin uses a short original piece to get you in — not a move of the original plot.', 'assets/posters/a-dark-room.jpg', 1920, 1080, 'center', '["assets/posters/a-dark-room.jpg"]', '[[1920,1080]]', '[1,2,6,22,69]', 61, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('paperclips', 'Universal Paperclips', '', '', 'Frank Lantz', '', '', 9.3, '33.1万', 0, 2017, 'idle', '["放置","模拟"]', 240, 0.04, 'clicker', 'https://www.decisionproblem.com/paperclips/', 0, 0, 0, 0, 0, 1, 0, 'long', '', '', '先别一支回形针。然后别完整个宇宙。', 'Make one paperclip. Then paperclip the universe.', '生产力、市场、自主。试玩舱只保留「再别一支」和三项升级，原作的哲学在完整版。', 'Production, market, autonomy. The cabin keeps “make another” and three upgrades. The philosophy is in the full game.', 'assets/posters/paperclips.jpg', 917, 709, 'center', '["assets/posters/paperclips.jpg"]', '[[917,709]]', '[2,4,10,28,56]', 62, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('diep-io', 'Diep.io', '', '', 'Diep.io', '', '', 8.8, '152.0万', 0, 2016, 'action', '["动作","IO"]', 230, 0.12, 'io', 'https://diep.io/', 0, 0, 1, 0, 0, 0, 0, 'mid', '', '', '在圆形的池子里长大。瞄准，不要停。', 'Grow in a round pool. Aim. Do not stop.', '吃点、升级、改炮台。试玩舱是简化 IO：跟随指针、吞光点、躲开更大的圆。', 'Eat dots, upgrade, change the turret. The cabin is a simpler IO: follow the pointer, swallow lights, dodge larger circles.', 'assets/posters/diep-io.png', 643, 526, 'center', '["assets/posters/diep-io.png"]', '[[643,526]]', '[4,8,18,36,34]', 63, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('agar-io', 'Agar.io', '', '', 'Miniclip', '', '', 8.6, '201.4万', 0, 2015, 'action', '["动作","IO"]', 145, 0.13, 'io', 'https://agar.io/', 0, 0, 1, 0, 0, 0, 0, 'mid', '', '', '你是一滴细胞。变大，或被吞掉。', 'You are a cell. Grow, or get eaten.', '经典 IO 吞食。试玩舱用光点和几个游荡的圆代替完整大厅。', 'Classic IO eating. The cabin uses lights and a few wandering circles in place of a full lobby.', 'assets/posters/agar-io.png', 1200, 630, 'center', '["assets/posters/agar-io.png"]', '[[1200,630]]', '[5,9,20,33,33]', 64, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('password-game', 'The Password Game', '', '', 'Neal Agarwal', '', '', 9, '54.7万', 0, 2023, 'story', '["解谜","规则"]', 220, 0.08, 'story', 'https://neal.fun/password-game/', 0, 0, 0, 1, 0, 0, 0, 'mid', '', '', '规则下一秒才会告诉你。密码得跟着改。', 'The rule shows up a second later. The password has to change with it.', '原作的二十多条规则不能搬进原型。试玩舱是一段原创的「规则会变」短谜。', 'The original’s twenty-plus rules cannot move into this prototype. The cabin is a short original puzzle where the rule keeps changing.', 'assets/posters/password-game.jpg', 1600, 900, 'center 28%', '["assets/posters/password-game.jpg"]', '[[1600,900]]', '[3,6,14,29,48]', 65, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('alchemy-2', 'Little Alchemy 2', '', '', 'Recloak', '', '', 8.9, '47.5万', 0, 2017, 'puzzle', '["解谜","合成"]', 130, 0.1, 'merge', 'https://littlealchemy2.com/', 0, 0, 0, 1, 0, 0, 0, 'mid', '', '', '土、气、火、水。其余的，自己拼。', 'Earth, air, fire, water. The rest, you combine.', '原作是元素合成图鉴。试玩舱用 2048 规则感受「合在一起会变」的手感。', 'The original is an element atlas. The cabin uses 2048 rules to feel “put two things together and they change.”', 'assets/posters/alchemy-2.jpg', 1800, 945, 'center', '["assets/posters/alchemy-2.jpg"]', '[[1800,945]]', '[2,5,16,35,42]', 66, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('krunker', 'Krunker', '', '', 'Yendis', '', '', 8.4, '88.9万', 0, 2019, 'action', '["射击","动作"]', 30, 0.12, 'io', 'https://krunker.io/', 0, 0, 1, 0, 0, 0, 1, 'mid', '', '落地就要动', '浏览器里的快节奏射击。落地就要动。', 'A fast shooter in the browser. Move the moment you land.', '原作是完整 FPS。试玩舱不模拟枪械，用 IO 场感代替「移动和存活」。', 'The original is a full FPS. The cabin does not simulate guns. It uses IO feel for “move and stay alive.”', 'assets/posters/krunker.jpg', 1280, 720, 'center', '["assets/posters/krunker.jpg"]', '[[1280,720]]', '[6,10,22,34,28]', 67, 1794591927039, 'Move the moment you land', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('watermelon', '合成大西瓜', 'Merge Watermelon', 'hechengdaxigua xigua daxigua', '公开网页游戏', '', '', 8.2, '310.5万', 0, 2021, 'puzzle', '["休闲","合成"]', 15, 0.14, 'merge', '', 0, 0, 1, 1, 0, 0, 0, 'short', '', '', '小圆碰小圆。大家都在等那颗西瓜。', 'Small circles bump small circles. Everyone is waiting for that watermelon.', '原作是下落合成。试玩舱用数字合成代替物理碰撞，手感相近，规则完整可玩。', 'The original is a drop-and-merge. The cabin uses number merges in place of physics. The feel is close; the rule is fully playable.', 'assets/posters/watermelon.png', 421, 237, 'center', '["assets/posters/watermelon.png"]', '[[421,237]]', '[7,12,24,31,26]', 68, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('slither', 'Slither.io', '', '', 'Steve Howse', '', '', 8.5, '176.3万', 0, 2016, 'action', '["动作","IO"]', 155, 0.13, 'io', 'https://slither.io/', 0, 0, 1, 0, 0, 0, 0, 'mid', '', '', '变长，围人，别把自己绕进去。', 'Grow long, wrap people, do not loop yourself.', '蛇形 IO。试玩舱同样是光点场，用来感受追逐和体积。', 'A snake IO. The cabin is the same light field, for chase and size.', 'assets/posters/slither.png', 1358, 624, 'center 42%', '["assets/posters/slither.png"]', '[[1358,624]]', '[5,9,21,35,30]', 69, 1794591927039, '', '', '');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('harbor', '港口调度', 'Harbor Dispatch', 'gangkoudiaodu gangkou', '何予', '', '', 8.4, '12.8万', 0, 2026, 'idle', '["工坊","调度"]', 230, 0.09, 'story', '', 1, 1, 0, 1, 0, 0, 0, 'mid', '', '', '潮汐窗口只有八分钟。把船位、吊机和夜班排开。', 'The tide window is eight minutes. Slot the berths, cranes, and night shift.', 'Fable 5.2 工坊示例，非正式上架。试玩舱用短选择表现调度压力。', 'A Fable 5.2 workshop sample, not a live listing. The cabin uses short choices to show dispatch pressure.', '', 960, 540, 'center', '["早班船位","吊机冲突","夜潮"]', '[]', '[4,8,18,30,40]', 70, 1794591927039, '', 'listed', 'heyu');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('night-port', '夜航港', 'Night Port', 'yehanggang yehang', '林澄', '', '', 8.7, '9.6万', 0, 2026, 'story', '["工坊","叙事"]', 265, 0.11, 'story', '', 1, 1, 0, 1, 0, 1, 1, 'mid', '', '哪一盏灯继续亮着', '广播里只剩潮声。你要决定哪一盏灯继续亮着。', 'The radio is only tide. You decide which lamp stays on.', 'Fable 5.2 工坊示例。试玩舱是一段原创短选择，不是完整剧情。', 'A Fable 5.2 workshop sample. The cabin is a short original choice, not the full plot.', '', 960, 540, 'center', '["防波堤","值班室","最后一盏灯"]', '[]', '[3,6,12,22,57]', 71, 1794591927039, 'Which lamp stays on', 'listed', 'lincheng');
INSERT INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId) VALUES ('lift', '电梯将至', 'Lift Incoming', 'diantijiangzhi dianti', '阿北', '', '', 8.1, '7.4万', 0, 2026, 'action', '["工坊","反应"]', 15, 0.14, 'story', '', 1, 1, 0, 1, 0, 0, 0, 'short', '', '', '楼层数字在跳。在门关上前把正确的人送回家。', 'Floor numbers jump. Get the right person home before the doors close.', 'Fable 5.2 工坊示例。试玩舱用选择代替反应操作。', 'A Fable 5.2 workshop sample. The cabin uses choices in place of reaction play.', '', 960, 540, 'center', '["厅门","楼层灯","关门瞬间"]', '[]', '[5,10,20,28,37]', 72, 1794591927039, '', 'listed', '阿北');
