INSERT INTO reviews (id, gameId, userId, name, s, score, t, at, deleted, seed) VALUES ('seed-warm-toy-room-0', 'warm-toy-room', 'dafeiyu', '大肥鱼', '作者', NULL, '沿着书本和线轴，找到散落在房间里的五枚星光。', 1794591927046, 0, 1);
INSERT INTO reviews (id, gameId, userId, name, s, score, t, at, deleted, seed) VALUES ('seed-feiche-3d-0', 'feiche-3d', 'fable52games', 'fable52.games', '作者', NULL, '漂移攒能量，氮气和道具，四条复古赛道。原页可玩。', 1794591927046, 0, 1);
