INSERT INTO reviews (id, gameId, userId, name, s, score, t, at, deleted, seed) VALUES ('seed-last-light-0', 'last-light', 'deny224', 'Deny224', '作者', NULL, '灯笼就是血条。免费 3D 生存，浏览器即开。', 1794591927047, 0, 1);
INSERT INTO reviews (id, gameId, userId, name, s, score, t, at, deleted, seed) VALUES ('seed-last-light-1', 'last-light', '即玩编辑', '即玩编辑', '好评', NULL, '夜林、营火、野蛮人都在实机图里，不是概念图。', 1794591867047, 0, 1);
INSERT INTO reviews (id, gameId, userId, name, s, score, t, at, deleted, seed) VALUES ('seed-akoben-0', 'akoben', 'eddie-forson', 'Eddie Forson', '作者', NULL, '打断两只膝盖，它就会跪下。序章 Boss 已可在浏览器打。', 1794591927047, 0, 1);
