INSERT INTO reviews (id, gameId, userId, name, s, score, t, at, deleted, seed) VALUES ('seed-mustache-protocol-0', 'mustache-protocol', 'screentime', 'ScreenTime', '好评', NULL, '早期评价说又好笑又好玩，浏览器可玩。', 1794591927047, 0, 1);
INSERT INTO reviews (id, gameId, userId, name, s, score, t, at, deleted, seed) VALUES ('seed-laps-0', 'laps', 'dan-clarke', 'Dan Clarke', '作者', NULL, '周末和 Claude 做的。Xbox 打开 Edge 就能玩。', 1794591927047, 0, 1);
