INSERT INTO reviews (id, gameId, userId, name, s, score, t, at, deleted, seed) VALUES ('seed-saltline-0', 'saltline', 'imteccin', 'imteccin', '好评', NULL, 'Amazing game, Fable 5.2 is insane。', 1794591927047, 0, 1);
